import random

def check(d):
    M = 1810
    forbidden_min = M - d
    forbidden_max = M + d

    for _ in range(1000):
        sums = {0}
        current_total = 0
        while current_total < M:
            possible_xs = []
            for x in range(1, 101):
                possible = True
                for s in sums:
                    if forbidden_min <= s + x <= forbidden_max:
                        possible = False
                        break
                if possible:
                    possible_xs.append(x)

            if not possible_xs:
                break

            x = random.choice(possible_xs)
            new_sums = set()
            for s in sums:
                new_sums.add(s + x)
            sums.update(new_sums)
            current_total = max(sums)

        if current_total >= M:
            return True
    return False

print(f"d=46 possible? {check(46)}")
print(f"d=47 possible? {check(47)}")
print(f"d=45 possible? {check(45)}")
